-- Initial schema for the multi-tenant workspace platform.
--
-- Authored as explicit SQL rather than generated, because the three guarantees
-- that matter most here are easier to read — and to review — as DDL than as
-- MigrationBuilder calls: the partial unique index on pending invitations, the
-- composite foreign key that pins a task to its project *within one tenant*,
-- and the jsonb audit metadata column.
--
-- Identifiers are UUID v7 generated by the application: globally unique, but
-- time-ordered, so inserts stay at the right-hand edge of each B-tree instead
-- of scattering across it.

CREATE TABLE users (
    id                    uuid                     NOT NULL,
    email                 character varying(254)   NOT NULL,
    normalized_email      character varying(254)   NOT NULL,
    password_hash         character varying(512)   NOT NULL,
    display_name          character varying(80)    NOT NULL,
    is_disabled           boolean                  NOT NULL DEFAULT false,
    last_login_at         timestamp with time zone NULL,
    failed_login_attempts integer                  NOT NULL DEFAULT 0,
    locked_until          timestamp with time zone NULL,
    created_at            timestamp with time zone NOT NULL,
    updated_at            timestamp with time zone NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id)
);

-- Uniqueness is on the normalized column, so "A@x.com" cannot register
-- alongside "a@x.com".
CREATE UNIQUE INDEX ix_users_normalized_email ON users (normalized_email);

CREATE TABLE organizations (
    id                 uuid                     NOT NULL,
    name               character varying(100)   NOT NULL,
    slug               character varying(48)    NOT NULL,
    created_by_user_id uuid                     NOT NULL,
    created_at         timestamp with time zone NOT NULL,
    updated_at         timestamp with time zone NOT NULL,
    CONSTRAINT pk_organizations PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_organizations_slug ON organizations (slug);

-- The membership row is the authoritative answer to both "may this user see
-- this tenant at all?" and "what may they do inside it?". Nothing about
-- authorization is carried in a token.
CREATE TABLE memberships (
    id              uuid                     NOT NULL,
    organization_id uuid                     NOT NULL,
    user_id         uuid                     NOT NULL,
    role            integer                  NOT NULL,
    joined_at       timestamp with time zone NOT NULL,
    invitation_id   uuid                     NULL,
    created_at      timestamp with time zone NOT NULL,
    updated_at      timestamp with time zone NOT NULL,
    CONSTRAINT pk_memberships PRIMARY KEY (id),
    CONSTRAINT fk_memberships_organizations_organization_id
        FOREIGN KEY (organization_id) REFERENCES organizations (id) ON DELETE CASCADE,
    CONSTRAINT fk_memberships_users_user_id
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX ix_memberships_organization_id_user_id
    ON memberships (organization_id, user_id);

-- Supports "which organizations am I in?", the one read on this table that is
-- deliberately not tenant-scoped.
CREATE INDEX ix_memberships_user_id ON memberships (user_id);

CREATE INDEX ix_memberships_organization_id_role ON memberships (organization_id, role);

CREATE TABLE invitations (
    id                   uuid                     NOT NULL,
    organization_id      uuid                     NOT NULL,
    email                character varying(254)   NOT NULL,
    role                 integer                  NOT NULL,
    token_hash           character varying(128)   NOT NULL,
    status               integer                  NOT NULL,
    expires_at           timestamp with time zone NOT NULL,
    invited_by_user_id   uuid                     NOT NULL,
    accepted_at          timestamp with time zone NULL,
    accepted_by_user_id  uuid                     NULL,
    revoked_at           timestamp with time zone NULL,
    delivery_status      integer                  NOT NULL,
    delivered_at         timestamp with time zone NULL,
    delivery_attempts    integer                  NOT NULL DEFAULT 0,
    delivery_error       character varying(512)   NULL,
    created_at           timestamp with time zone NOT NULL,
    updated_at           timestamp with time zone NOT NULL,
    CONSTRAINT pk_invitations PRIMARY KEY (id),
    CONSTRAINT fk_invitations_organizations_organization_id
        FOREIGN KEY (organization_id) REFERENCES organizations (id) ON DELETE CASCADE,
    -- Restrict, not cascade: deleting a user must not silently erase the
    -- record of who invited whom.
    CONSTRAINT fk_invitations_users_invited_by_user_id
        FOREIGN KEY (invited_by_user_id) REFERENCES users (id) ON DELETE RESTRICT
);

-- Redemption is a lookup by hash; the token itself is never stored.
CREATE UNIQUE INDEX ix_invitations_token_hash ON invitations (token_hash);

CREATE INDEX ix_invitations_organization_id_status ON invitations (organization_id, status);

-- At most one *pending* invitation per address per organization. A partial
-- index says exactly that, without blocking a fresh invitation once the first
-- is accepted, revoked or expired. (1 = InvitationStatus.Pending.)
CREATE UNIQUE INDEX ix_invitations_pending_per_email
    ON invitations (organization_id, email)
    WHERE status = 1;

CREATE TABLE projects (
    id                 uuid                     NOT NULL,
    organization_id    uuid                     NOT NULL,
    name               character varying(120)   NOT NULL,
    slug               character varying(48)    NOT NULL,
    description        character varying(2000)  NULL,
    status             integer                  NOT NULL,
    created_by_user_id uuid                     NOT NULL,
    archived_at        timestamp with time zone NULL,
    created_at         timestamp with time zone NOT NULL,
    updated_at         timestamp with time zone NOT NULL,
    CONSTRAINT pk_projects PRIMARY KEY (id),
    -- Alternate key that lets children reference (organization, project) as a
    -- unit. This is what makes a cross-tenant task unrepresentable rather than
    -- merely prevented in application code.
    CONSTRAINT ak_projects_organization_id_id UNIQUE (organization_id, id),
    CONSTRAINT fk_projects_organizations_organization_id
        FOREIGN KEY (organization_id) REFERENCES organizations (id) ON DELETE CASCADE
);

-- Project handles are unique per tenant: two organizations may each have a
-- "website-redesign".
CREATE UNIQUE INDEX ix_projects_organization_id_slug ON projects (organization_id, slug);

CREATE INDEX ix_projects_organization_id_status ON projects (organization_id, status);

CREATE TABLE tasks (
    id                 uuid                     NOT NULL,
    organization_id    uuid                     NOT NULL,
    project_id         uuid                     NOT NULL,
    title              character varying(200)   NOT NULL,
    description        character varying(5000)  NULL,
    status             integer                  NOT NULL,
    priority           integer                  NOT NULL,
    assignee_user_id   uuid                     NULL,
    created_by_user_id uuid                     NOT NULL,
    due_at             timestamp with time zone NULL,
    completed_at       timestamp with time zone NULL,
    created_at         timestamp with time zone NOT NULL,
    updated_at         timestamp with time zone NOT NULL,
    CONSTRAINT pk_tasks PRIMARY KEY (id),
    -- Composite: a task's organization must match its project's organization,
    -- enforced by the database rather than trusted from code.
    CONSTRAINT fk_tasks_projects_organization_id_project_id
        FOREIGN KEY (organization_id, project_id)
        REFERENCES projects (organization_id, id) ON DELETE CASCADE,
    -- A deleted user leaves their tasks in place, unassigned.
    CONSTRAINT fk_tasks_users_assignee_user_id
        FOREIGN KEY (assignee_user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_tasks_organization_id_project_id_status
    ON tasks (organization_id, project_id, status);

CREATE INDEX ix_tasks_organization_id_assignee_user_id
    ON tasks (organization_id, assignee_user_id);

-- Audit entries are historical facts. They carry organization and actor ids as
-- plain values with no foreign keys, so the record of a deletion outlives the
-- organization, user or resource it describes — and so no ON DELETE action
-- ever has to mutate a row that the immutability trigger forbids changing.
CREATE TABLE audit_logs (
    id              uuid                     NOT NULL,
    organization_id uuid                     NULL,
    actor_user_id   uuid                     NULL,
    actor_email     character varying(254)   NULL,
    action          character varying(64)    NOT NULL,
    resource_type   character varying(32)    NOT NULL,
    resource_id     character varying(64)    NULL,
    metadata        jsonb                    NULL,
    ip_address      character varying(64)    NULL,
    user_agent      character varying(256)   NULL,
    correlation_id  character varying(64)    NULL,
    created_at      timestamp with time zone NOT NULL,
    updated_at      timestamp with time zone NOT NULL,
    CONSTRAINT pk_audit_logs PRIMARY KEY (id)
);

-- The audit screen reads one organization's trail newest-first.
CREATE INDEX ix_audit_logs_organization_id_created_at ON audit_logs (organization_id, created_at);

CREATE INDEX ix_audit_logs_organization_id_action ON audit_logs (organization_id, action);

CREATE INDEX ix_audit_logs_actor_user_id ON audit_logs (actor_user_id);

-- Refresh tokens are 256-bit random values stored only as SHA-256 hashes, and
-- they rotate on every use. chain_id ties a rotation chain together so one
-- statement can end a whole session.
CREATE TABLE refresh_tokens (
    id                    uuid                     NOT NULL,
    user_id               uuid                     NOT NULL,
    token_hash            character varying(128)   NOT NULL,
    expires_at            timestamp with time zone NOT NULL,
    revoked_at            timestamp with time zone NULL,
    revoked_reason        character varying(64)    NULL,
    replaced_by_token_id  uuid                     NULL,
    chain_id              uuid                     NOT NULL,
    created_by_ip         character varying(64)    NULL,
    user_agent            character varying(256)   NULL,
    created_at            timestamp with time zone NOT NULL,
    updated_at            timestamp with time zone NOT NULL,
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT fk_refresh_tokens_users_user_id
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX ix_refresh_tokens_token_hash ON refresh_tokens (token_hash);

CREATE INDEX ix_refresh_tokens_chain_id ON refresh_tokens (chain_id);
